    /**
     * Method to retrieve the ExternalAccount via ExternalAccountFetchOneSummary
     * @param 	summary ExternalAccountFetchOneSummary 
     * @return 	ExternalAccountFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public ExternalAccount getExternalAccount( ExternalAccountFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ExternalAccountFetchOneSummary arg cannot be null" );
    	
    	ExternalAccount entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	ExternalAccountValidator.getInstance().validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a ExternalAccount
        	// --------------------------------------
        	CompletableFuture<ExternalAccount> futureEntity = queryGateway.query(new FindExternalAccountQuery( new LoadExternalAccountFilter( summary.getExternalAccountId() ) ), ResponseTypes.instanceOf(ExternalAccount.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate ExternalAccount with id " + summary.getExternalAccountId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


