    /**
     * assign Customer on ExternalAccount
     * @param		command AssignCustomerToExternalAccountCommand	
     * @exception	ProcessingException
     */     
	public void assignCustomer( AssignCustomerToExternalAccountCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getExternalAccountId() );
		
		CustomerService childDelegate 	= CustomerService.getCustomerInstance();
		ExternalAccountService parentDelegate = ExternalAccountService.getExternalAccountInstance();			
		UUID childId = command.getAssignment().getCustomerId();
		Customer child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	ExternalAccountValidator.getInstance().validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Customer using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

